    {"id":411,"q":"حسب الجدول رقم (3)، مجموع أنصبة الورثة لا يجوز أن يتجاوز:","op":["أ. نصيب كل منهم حسب الجدول","ب. 100%","ج. 50%","د. 75%"],"a":"أ. نصيب كل منهم حسب الجدول","e":"الجدول رقم (3): لا يجوز أن يتجاوز مجموع الأنصبة الموزعة النسب المحددة في الجدول."},
    {"id":412,"q":"حسب الجدول رقم (3)، نصيب الابن الواحد من المعاش:","op":["أ. الثلث (1/3)","ب. النصف (1/2)","ج. السدس (1/6)","د. الربع (1/4)"],"a":"أ. الثلث (1/3)","e":"الجدول رقم (3): الابن - الثلث (1/3)."},
    {"id":413,"q":"حسب الجدول رقم (3)، نصيب الابنة الواحدة من المعاش:","op":["أ. الثلث (1/3)","ب. النصف (1/2)","ج. السدس (1/6)","د. الربع (1/4)"],"a":"أ. الثلث (1/3)","e":"الجدول رقم (3): الابنة - الثلث (1/3)."},
    {"id":414,"q":"حسب الجدول رقم (3)، في حال تعدد الأولاد، مجموع نصيبهم:","op":["أ. لا يزيد عن الثلثين (2/3)","ب. لا يزيد عن النصف (1/2)","ج. لا يزيد عن الربع (1/4)","د. لا يزيد عن السدس (1/6)"],"a":"أ. لا يزيد عن الثلثين (2/3)","e":"الجدول رقم (3): مجموع نصيب الأولاد - الثلثان (2/3)."},
    {"id":415,"q":"حسب الجدول رقم (3)، إذا كان للعامل والدان وزوجة، نصيب الزوجة يكون:","op":["أ. النصف (1/2)","ب. الثلث (1/3)","ج. الربع (1/4)","د. السدس (1/6)"],"a":"أ. النصف (1/2)","e":"الجدول رقم (3): في حال وجود زوجة ووالدين، تستحق الزوجة النصف."},
    {"id":416,"q":"حسب الجدول رقم (3)، إذا كان للعامل والدان وزوجة وأولاد:","op":["أ. الزوجة النصف والأولاد الثلثين","ب. الزوجة الثلث والأولاد النصف","ج. الزوجة السدس والأولاد الثلثين","د. الزوجة الربع والأولاد الثلثين"],"a":"أ. الزوجة النصف والأولاد الثلثين","e":"الجدول رقم (3): في حال وجود زوجة وأولاد وأبوين، تستحق الزوجة النصف والأولاد الثلثان."},
    {"id":417,"q":"حسب الجدول رقم (3)، يوزع المعاش بين الورثة المستحقين وفقاً:","op":["أ. للأنصبة المحددة في الجدول","ب. لقانون الإرث المدني","ج. للوصية","د. لاتفاق الورثة"],"a":"أ. للأنصبة المحددة في الجدول","e":"الجدول رقم (3): يوزع المعاش وفقاً للأنصبة المحددة في الجدول رقم (3) الملحق بهذا القانون."},
    {"id":418,"q":"حسب الجدول رقم (3)، في حال وفاة الأرملة، يعود نصيبها إلى:","op":["أ. الأولاد أو الورثة الآخرين حسب النسب","ب. الدولة","ج. النقابة","د. صاحب العمل"],"a":"أ. الأولاد أو الورثة الآخرين حسب النسب","e":"الجدول رقم (3): في حال وفاة الأرملة يعود نصيبها إلى الأولاد أو الورثة الآخرين حسب النسب."},
    {"id":419,"q":"حسب الجدول رقم (3)، إذا كان للعامل والدان فقط:","op":["أ. يستحق كل منهما النصف","ب. للأب النصف وللأم الثلث","ج. للأم النصف وللأب الثلث","د. للأب الثلثين"],"a":"أ. يستحق كل منهما النصف","e":"الجدول رقم (3): في حال عدم وجود زوجة أو أولاد، يستحق كل من الوالدين النصف."},
    {"id":420,"q":"حسب الجدول رقم (3)، في حال وجود أولاد ذكور وإناث:","op":["أ. يوزع نصيبهم بالتساوي","ب. للذكور الضعف","ج. للإناث الضعف","د. حسب العمر"],"a":"أ. يوزع نصيبهم بالتساوي","e":"الجدول رقم (3): يوزع نصيب الأولاد بالتساوي بينهم."},
    {"id":421,"q":"حسب الجدول رقم (3)، نصيب الأم من المعاش:","op":["أ. السدس إذا كان هناك أولاد","ب. النصف إذا كان هناك أولاد","ج. الثلث إذا كان هناك أولاد","د. الربع إذا كان هناك أولاد"],"a":"أ. السدس إذا كان هناك أولاد","e":"الجدول رقم (3): الأب أو الأم - السدس (1/6) في حال وجود أولاد."},
    {"id":422,"q":"حسب الجدول رقم (3)، نصيب الأب من المعاش:","op":["أ. السدس إذا كان هناك أولاد","ب. النصف إذا كان هناك أولاد","ج. الثلث إذا كان هناك أولاد","د. الربع إذا كان هناك أولاد"],"a":"أ. السدس إذا كان هناك أولاد","e":"الجدول رقم (3): الأب أو الأم - السدس (1/6) في حال وجود أولاد."},
    {"id":423,"q":"حسب الجدول رقم (3)، في حال وجود أخت وأخ:","op":["أ. يستحق كل منهما حصته","ب. للأخ الضعف","ج. للأخت الضعف","د. للأخ النصف"],"a":"أ. يستحق كل منهما حصته","e":"الجدول رقم (3): يوزع نصيب الإخوة والأخوات بالتساوي بينهم."},
    {"id":424,"q":"حسب الجدول رقم (3)، توزيع المعاش للزوجة إذا كان هناك ولد:","op":["أ. النصف","ب. الثلث","ج. الربع","د. السدس"],"a":"أ. النصف","e":"الجدول رقم (3): أرملة ولها ولد - النصف (1/2)."},
    {"id":425,"q":"حسب الجدول رقم (3)، الملاحظات المرفقة بالجدول توضح حالات خاصة مثل:","op":["أ. توزيع المعاش في حالة وفاة الزوجة","ب. توزيع المعاش في حالة وفاة الأب","ج. توزيع المعاش في حالة وفاة الأم","د. توزيع المعاش في حالة وفاة الابن"],"a":"أ. توزيع المعاش في حالة وفاة الزوجة","e":"الجدول رقم (3): الملاحظات توضح أنه في حال وفاة الأرملة يعود نصيبها إلى الأولاد أو الورثة الآخرين حسب النسب."},
    {"id":426,"q":"حسب المادة (13)، عقد العمل المبرم مع عامل في الأعمال غير النمطية:","op":["أ. يعتبر عقد عمل محددة المدة","ب. يعتبر عقد عمل غير محددة المدة","ج. لا يعتبر عقد عمل","د. يعتبر عقد عمل موسمي"],"a":"أ. يعتبر عقد عمل محددة المدة","e":"المادة (13): يعتبر العامل الذي يستخدم بانتظام بالقطعة في محل العمل أو الذي يقوم بسلسلة من الأعمال بالقطعة أنه عامل لمدة غير محدودة."},
    {"id":427,"q":"حسب المادة (14)، في حالة إصابة العامل بسبب من صاحب العمل، فإن التعويض:","op":["أ. يحسب على أساس أجره في وقت الإصابة","ب. يحسب على أساس الحد الأدنى للأجور","ج. لا يحسب","د. يحسب على أساس متوسط الأجر"],"a":"أ. يحسب على أساس أجره في وقت الإصابة","e":"المادة (14): إذا أصيب عامل إصابة عمل نتيجة سبب من أسباب العمل الذي يقوم به وجب على صاحب العمل تشغيله في عمل آخر مناسب بحالته، وإذا تضمن له الحق بالتعويض على أساس أجره في الوقت الذي أصابته فيه الإصابة."},
    {"id":428,"q":"حسب المادة (15)، إذا كان العقد غير مكتوب، فإن إثبات العقد يكون:","op":["أ. بطرق الإثبات القانونية","ب. غير ممكن","ج. شفهياً فقط","د. بموافقة النقابة"],"a":"أ. بطرق الإثبات القانونية","e":"المادة (15): يجوز للعامل إثبات حقوقه بجميع طرق الإثبات القانونية إذا لم يحرر عقد العمل كتابة."},
    {"id":429,"q":"حسب المادة (15)، يجب تحرير العقد باللغة العربية، وإذا كان العامل لا يجيد العربية:","op":["أ. يجب إرفاق نسخة مترجمة إلى اللغة التي يفهمها","ب. يتم التعامل بالإنجليزية","ج. يتم تعيين مترجم","د. يتم إلغاء العقد"],"a":"أ. يجب إرفاق نسخة مترجمة إلى اللغة التي يفهمها","e":"المادة (15): إذا كان العامل لا يجيد اللغة العربية وجب إرفاق نسخة مترجمة من العقد إلى لغة يفهمها."},
    {"id":430,"q":"حسب المادة (16)، في حال انتقال المؤسسة بطريق الإرث:","op":["أ. يبقى عقد العمل سارياً","ب. ينتهي العقد","ج. يتم تعديل العقد","د. يتم فسخ العقد"],"a":"أ. يبقى عقد العمل سارياً","e":"المادة (16): يبقى عقد العمل معمولاً به بغض النظر عن تغيير صاحب العمل بسبب انتقال المؤسسة بطريق الإرث."},
    {"id":431,"q":"حسب المادة (17)، إذا دفعت الضرورة لتكليف العامل بعمل مختلف:","op":["أ. يجب أن يكون ذلك في حدود طاقته","ب. يجب أن يكون ذلك في أي وقت","ج. يجب أن يكون ذلك بموافقة النقابة","د. يجب أن يكون ذلك بموافقة المحكمة"],"a":"أ. يجب أن يكون ذلك في حدود طاقته","e":"المادة (17): على أن يكون ذلك في حدود طاقته وفي حدود الظرف الذي اقتضى هذا العمل."},
    {"id":432,"q":"حسب المادة (18)، إذا أدى تغيير مكان العمل إلى تغيير مكان إقامة العامل:","op":["أ. لا يلزم العامل بذلك ما لم ينص العقد","ب. يلزم العامل بذلك دائماً","ج. يلزم العامل بموافقة النقابة","د. يلزم العامل بموافقة المحكمة"],"a":"أ. لا يلزم العامل بذلك ما لم ينص العقد","e":"المادة (18): لا يلزم العامل بالعمل في مكان غير المكان المخصص لعمله إذا أدى ذلك إلى تغيير مكان إقامته وذلك ما لم يرد نص صريح يجيز ذلك في عقد العمل."},
    {"id":433,"q":"حسب المادة (19)، العامل ملزم بتنفيذ أوامر صاحب العمل:","op":["أ. المتعلقة بتنفيذ العمل المتفق عليه، ضمن حدود لا تعرضه للخطر","ب. المتعلقة بكل شيء","ج. المتعلقة بوقت الراحة","د. المتعلقة بالإجازات"],"a":"أ. المتعلقة بتنفيذ العمل المتفق عليه، ضمن حدود لا تعرضه للخطر","e":"المادة (19): التزام بأوامر صاحب العمل المتعلقة بتنفيذ العمل المتفق عليه وذلك ضمن الحدود التي لا تعرضه للخطر."},
    {"id":434,"q":"حسب المادة (19)، على العامل أن يحافظ على أدوات العمل:","op":["أ. والمواد وسائر اللوازم الخاصة بعمله","ب. ويسمح للآخرين باستخدامها","ج. ويستخدمها في منزله","د. ويهملها"],"a":"أ. والمواد وسائر اللوازم الخاصة بعمله","e":"المادة (19): الحرص على حفظ الأشياء المسلمة إليه لتأدية العمل ومنها أدوات العمل والمواد وسائر اللوازم الخاصة بعمله."},
    {"id":435,"q":"حسب المادة (20)، إذا كان الاختراع متعلقاً بعمل صاحب العمل:","op":["أ. تكون الملكية الفكرية لصاحب العمل","ب. تكون الملكية الفكرية للعامل","ج. تكون الملكية الفكرية للدولة","د. تكون مشتركة"],"a":"أ. تكون الملكية الفكرية لصاحب العمل","e":"المادة (20): إذا كان الاختراع متعلقاً بعمل صاحب العمل وتم باستخدام إمكانياته فتكون الملكية الفكرية لصاحب العمل."},
    {"id":436,"q":"حسب المادة (21)، انتهاء عقد العمل بانتهاء المدة المحددة:","op":["أ. يعتبر سبباً مشروعاً لانتهاء العقد","ب. لا يعتبر سبباً مشروعاً","ج. يعتبر فسخاً","د. يعتبر استقالة"],"a":"أ. يعتبر سبباً مشروعاً لانتهاء العقد","e":"المادة (21): ينتهي عقد العمل إذا انتهت المدة المحددة في العقد."},
    {"id":437,"q":"حسب المادة (22)، وفاة العامل:","op":["أ. تنهي عقد العمل","ب. لا تنهي عقد العمل","ج. تعلق العقد","د. تنقل العقد للورثة"],"a":"أ. تنهي عقد العمل","e":"المادة (21): ينتهي عقد العمل إذا توفي العامل."},
    {"id":438,"q":"حسب المادة (23)، في عقد العمل غير محدد المدة، الإشعار يجب أن يكون:","op":["أ. قبل شهر واحد","ب. قبل أسبوع","ج. قبل يومين","د. قبل 3 أشهر"],"a":"أ. قبل شهر واحد","e":"المادة (23): فيترتب عليه إشعار الطرف الآخر خطياً قبل شهر واحد على الأقل."},
    {"id":439,"q":"حسب المادة (23)، إذا أنهي العقد دون إشعار، يلتزم الطرف المفصل بدفع تعويض:","op":["أ. تحدده المحكمة المختصة","ب. تحدده النقابة","ج. تحدده الوزارة","د. تحدده المحكمة العليا"],"a":"أ. تحدده المحكمة المختصة","e":"المادة (23): ويلتزم الطرف الذي أنهى العقد دون إشعار بتعويض الطرف الآخر عن الضرر الذي لحقه."},
    {"id":440,"q":"حسب المادة (24)، فصل العامل بسبب تقدمه بشكوى:","op":["أ. غير مشروع","ب. مشروع","ج. مشروع بموافقة النقابة","د. مشروع بموافقة الوزير"],"a":"أ. غير مشروع","e":"المادة (24): لا يجوز لصاحب العمل فصل العامل أو اتخاذ إجراء تأديبي بحقه بسبب الأسباب تتصل بالشكاوى والمطالبات التي تقدم بها العامل."},
    {"id":441,"q":"حسب المادة (25)، لا يجوز فسخ العقد بسبب الشكاوى والمطالبات:","op":["أ. التي يقدمها العامل للجهات المختصة","ب. التي يقدمها صاحب العمل","ج. التي تقدمها النقابة","د. التي تقدمها المحكمة"],"a":"أ. التي يقدمها العامل للجهات المختصة","e":"المادة (24): لا يجوز لصاحب العمل فصل العامل أو اتخاذ إجراء تأديبي بحقه بسبب الأسباب تتصل بالشكاوى والمطالبات التي تقدم بها العامل."},
    {"id":442,"q":"حسب المادة (26)، في حالة فسخ العقد من قبل صاحب العمل دون سبب مشروع:","op":["أ. يحق للعامل أجرة المدة المتبقية","ب. لا يحق للعامل شيء","ج. يحق للعامل تعويض تأديبي","د. يحق للعامل نصف الأجر"],"a":"أ. يحق للعامل أجرة المدة المتبقية","e":"المادة (26): إذا أنهى صاحب العمل عقد العمل قبل انتهاء مدته دون سبب مشروع فيستحق العامل أجرة المدة المتبقية من العقد."},
    {"id":443,"q":"حسب المادة (27)، الغياب دون عذر لمدة تزيد على 7 أيام متصلة:","op":["أ. يؤدي إلى فقدان العامل حقه في التعويض عن مدة الغياب","ب. يؤدي إلى خصم الأجر","ج. يؤدي إلى إنذار","د. لا يؤدي إلى شيء"],"a":"أ. يؤدي إلى فقدان العامل حقه في التعويض عن مدة الغياب","e":"المادة (27): فيفقد العامل حقه في التعويض عن مدة الغياب."},
    {"id":444,"q":"حسب المادة (28)، إذا انتحل العامل شخصية أخرى:","op":["أ. يحق لصاحب العمل فصله دون إشعار","ب. يحق لصاحب العمل فصله بعد إنذار","ج. لا يحق لصاحب العمل فصله","د. يحق لصاحب العمل فصله بموافقة النقابة"],"a":"أ. يحق لصاحب العمل فصله دون إشعار","e":"المادة (28): إذا انتحل العامل شخصية أو هوية غيره أو قدم شهادات أو وثائق مزورة."},
    {"id":445,"q":"حسب المادة (28)، إذا خالف العامل النظام الداخلي للمنشأة بشكل جسيم:","op":["أ. يحق لصاحب العمل فصله دون إشعار","ب. يحق لصاحب العمل فصله بعد إنذار","ج. لا يحق لصاحب العمل فصله","د. يحق لصاحب العمل فصله بموافقة النقابة"],"a":"أ. يحق لصاحب العمل فصله دون إشعار","e":"المادة (28): إذا خالف العامل النظام الداخلي للمؤسسة بما في ذلك شروط سلامة العمل مرتين بعد إنذاره كتابياً."},
    {"id":446,"q":"حسب المادة (29)، إذا أخطر العامل صاحب العمل بإنهاء العقد بسبب سوء المعاملة:","op":["أ. يحق له إنهاء العقد دون إشعار","ب. لا يحق له إنهاء العقد","ج. يحق له إنهاء العقد مع إشعار","د. يحق له إنهاء العقد بموافقة النقابة"],"a":"أ. يحق له إنهاء العقد دون إشعار","e":"المادة (29): يحق للعامل ترك العمل دون إشعار إذا اعتدى عليه صاحب العمل أو من يمثله بالضرب أو التحقير."},
    {"id":447,"q":"حسب المادة (30)، مكافأة نهاية الخدمة للعامل الذي استقال بسبب مشروع:","op":["أ. يستحق كامل المكافأة","ب. يستحق نصف المكافأة","ج. لا يستحق شيئاً","د. يستحق ربع المكافأة"],"a":"أ. يستحق كامل المكافأة","e":"المادة (30): إذا أنهى العامل العقد لسبب مشروع فيستحق كامل المكافأة."},
    {"id":448,"q":"حسب المادة (30)، إذا استقال العامل دون سبب مشروع ولم يكمل سنة:","op":["أ. لا يستحق مكافأة نهاية الخدمة","ب. يستحق نصف المكافأة","ج. يستحق ربع المكافأة","د. يستحق ثلث المكافأة"],"a":"أ. لا يستحق مكافأة نهاية الخدمة","e":"المادة (30): إذا أنهى العامل العقد دون سبب مشروع فيستحق نصف المكافأة المنصوص عليها في المادة (33) من هذا القانون."},
    {"id":449,"q":"حسب المادة (45)، إذا لم ينص العقد على الأجر، يتم تحديده:","op":["أ. بأجر المثل","ب. بموجب العرف","ج. بموجب القانون","د. بموجب المحكمة"],"a":"أ. بأجر المثل","e":"المادة (45): يحدد مقدار الأجر في العقد وإذا لم ينص عقد العمل عليه فيأخذ العامل الأجر المقدر لعمل من نفس النوع إن وجد وإلا قدر طبقاً للعرف."},
    {"id":450,"q":"حسب المادة (46)، يجب دفع الأجر في موعد لا يتجاوز:","op":["أ. سبعة أيام من تاريخ الاستحقاق","ب. أسبوعين","ج. شهر","د. نهاية الشهر"],"a":"أ. سبعة أيام من تاريخ الاستحقاق","e":"المادة (46): يدفع الأجر وبدل العمل الإضافي خلال مدة لا تزيد على سبعة أيام من تاريخ استحقاقه."},
    {"id":451,"q":"حسب المادة (47)، لا يجوز حسم أي مبلغ من الأجر إلا في الحالات:","op":["أ. التي يجيزها القانون","ب. التي يطلبها العامل","ج. التي تطلبها النقابة","د. التي يطلبها صاحب العمل"],"a":"أ. التي يجيزها القانون","e":"المادة (47): لا يجوز حسم أي مبلغ من أجر العامل إلا في الحالات التالية: اشتراكات الضمان الاجتماعي وأقساطها المستحقة على العامل والحسيمات الواجب إجراؤها بموجب القوانين الأخرى."},
    {"id":452,"q":"حسب المادة (48)، العقوبة المالية لا تزيد عن أجر:","op":["أ. ثلاثة أيام","ب. يومين","ج. أسبوع","د. عشرة أيام"],"a":"أ. ثلاثة أيام","e":"المادة (48): ولا يجوز أن تزيد الغرامة على أجر ثلاثة أيام في الشهر الواحد."},
    {"id":453,"q":"حسب المادة (48)، يجب أن يتم إشعار العامل بالعقوبة خلال:","op":["أ. أسبوع من تاريخ ارتكاب المخالفة","ب. يومين","ج. شهر","د. سنة"],"a":"أ. أسبوع من تاريخ ارتكاب المخالفة","e":"المادة (48): ولا يجوز أن يتخذ هذا الإجراء إلا بعد إعطاء العامل فرصة للدفاع عن نفسه قبل فرض العقوبة عليه."},
    {"id":454,"q":"حسب المادة (49)، الخصم من الأجر بسبب إهمال العامل لا يزيد عن:","op":["أ. 10% من أجره الشهري","ب. 20% من أجره الشهري","ج. 5% من أجره الشهري","د. 50% من أجره الشهري"],"a":"أ. 10% من أجره الشهري","e":"المادة (49): على ألا يزيد ما يقتطع على 10% من أجر العامل في الشهر الواحد."},
    {"id":455,"q":"حسب المادة (50)، إذا توقف العمل بسبب قوة قاهرة، يستحق العامل:","op":["أ. أجره عن 10 أيام الأولى","ب. أجره عن شهر كامل","ج. أجره عن أسبوع كامل","د. نصف أجره"],"a":"أ. أجره عن 10 أيام الأولى","e":"المادة (50): فيستحق العامل الأجر عن مدة لا تزيد على العشرة أيام الأولى من توقف العمل خلال السنة."},
    {"id":456,"q":"حسب المادة (51)، الأجور المستحقة للعامل هي ديون:","op":["أ. ممتازة من الدرجة الأولى","ب. عادية","ج. ممتازة من الدرجة الثانية","د. ممتازة من الدرجة الثالثة"],"a":"أ. ممتازة من الدرجة الأولى","e":"المادة (51): تعتبر الأجور والمبالغ المستحقة بموجب أحكام هذا القانون للعامل أو ورثته أو أي مستحقين لها بعد وفاته ديوناً ممتازة امتيازاً عاماً من الدرجة الأولى."},
    {"id":457,"q":"حسب المادة (52)، اللجنة الثلاثية تحدد الحد الأدنى للأجور:","op":["أ. بناءً على مؤشرات تكاليف المعيشة","ب. بناءً على طلب النقابة","ج. بناءً على طلب صاحب العمل","د. بناءً على طلب الوزير"],"a":"أ. بناءً على مؤشرات تكاليف المعيشة","e":"المادة (52): على أن يؤخذ بعين الاعتبار مؤشرات تكاليف المعيشة التي تصدرها الجهات الرسمية المختصة."},
    {"id":458,"q":"حسب المادة (53)، عقوبة عدم الالتزام بالحد الأدنى للأجور هي:","op":["أ. غرامة 500-1000 دينار","ب. غرامة 100-500 دينار","ج. الحبس","د. إغلاق المؤسسة"],"a":"أ. غرامة 500-1000 دينار","e":"المادة (53): يعاقب صاحب العمل بغرامة لا تقل عن خمسمائة دينار ولا تزيد على ألف دينار عن كل حالة يدفع فيها إلى عامل أجراً يقل عن الحد الأدنى للأجور."},
    {"id":459,"q":"حسب المادة (54)، سلطة الأجور تختص بنظر الدعاوى المتعلقة:","op":["أ. بالأجور","ب. بالنقابات","ج. بتصاريح العمل","د. بالتأمين الصحي"],"a":"أ. بالأجور","e":"المادة (54): تتولى سلطة الأجور النظر في الدعاوى المتعلقة بالأجور في تلك المنطقة."},
    {"id":460,"q":"حسب المادة (56)، لا يجوز تشغيل العامل أكثر من 48 ساعة:","op":["أ. في الأسبوع","ب. في اليوم","ج. في الشهر","د. في السنة"],"a":"أ. في الأسبوع","e":"المادة (56): لا يجوز تشغيل العامل أكثر من ثماني ساعات يومياً أو ثمان وأربعين ساعة في الأسبوع."},
    {"id":461,"q":"حسب المادة (57)، ساعات العمل الإضافية في حالات الجرد السنوي لا تزيد عن:","op":["أ. 30 يومًا في السنة","ب. 20 يومًا","ج. 15 يومًا","د. 45 يومًا"],"a":"أ. 30 يومًا في السنة","e":"المادة (57): بشرط أن لا يزيد عدد الأيام التي تنطبق عليها أحكام هذه الفقرة على ثلاثين يوماً في السنة."},
    {"id":462,"q":"حسب المادة (58)، أحكام ساعات العمل لا تسري على:","op":["أ. العمال الذين يسافرون في عملهم","ب. العمال الذين يعملون في المكاتب","ج. العمال الذين يعملون في المصانع","د. العمال الذين يعملون في البناء"],"a":"أ. العمال الذين يسافرون في عملهم","e":"المادة (58): وكذلك على العاملين الذين تتطلب طبيعة أعمالهم السفر والتنقل داخل المملكة أو خارجها."},
    {"id":463,"q":"حسب المادة (59)، العمل الإضافي يستحق أجراً إضافياً لا يقل عن:","op":["أ. 25% من الأجر المعتاد","ب. 50% من الأجر المعتاد","ج. 75% من الأجر المعتاد","د. 100% من الأجر المعتاد"],"a":"أ. 25% من الأجر المعتاد","e":"المادة (59): على أن يتقاضى العامل عن ساعة العمل الإضافية أجراً لا يقل عن 25% من أجره المعتاد."},
    {"id":464,"q":"حسب المادة (60)، العطلة الأسبوعية يجب أن تكون:","op":["أ. يوم الجمعة","ب. يوم السبت","ج. يوم الأحد","د. يوم الخميس"],"a":"أ. يوم الجمعة","e":"المادة (60): يكون يوم الجمعة من كل أسبوع يوم العطلة الأسبوعية للعامل."},
    {"id":465,"q":"حسب المادة (61)، الإجازة السنوية مدتها لا تقل عن:","op":["أ. أربعة عشر يوماً","ب. واحد وعشرون يوماً","ج. ثلاثين يوماً","د. سبعة أيام"],"a":"أ. أربعة عشر يوماً","e":"المادة (61): لكل عامل الحق في إجازة سنوية بأجر كامل لمدة لا تقل عن أربعة عشر يوماً عن كل سنة خدمة."},
    {"id":466,"q":"حسب المادة (62)، التعويض عن الإجازة غير المأخوذة:","op":["أ. يومان عن كل يوم إجازة","ب. يوم واحد عن كل يوم","ج. نصف يوم عن كل يوم","د. ربع يوم عن كل يوم"],"a":"أ. يومان عن كل يوم إجازة","e":"المادة (62): إذا لم يؤد العامل إجازته السنوية فيستحق تعويضاً عن كل يوم إجازة لم يستعمله."},
    {"id":467,"q":"حسب المادة (64)، التنازل عن الإجازة السنوية يعتبر:","op":["أ. باطلاً","ب. صحيحاً","ج. جائزاً بموافقة النقابة","د. جائزاً بموافقة الوزير"],"a":"أ. باطلاً","e":"المادة (64): كل اتفاق يقضي بتنازل العامل عن إجازته السنوية أو عن جزء منها يعتبر باطلاً."},
    {"id":468,"q":"حسب المادة (65)، الإجازة المرضية مدتها لا تتجاوز:","op":["أ. أربعة عشر يوماً","ب. واحد وعشرون يوماً","ج. ثلاثين يوماً","د. خمسة وأربعين يوماً"],"a":"أ. أربعة عشر يوماً","e":"المادة (65): يستحق العامل إجازة مرضية بأجر كامل لمدة لا تتجاوز أربعة عشر يوماً في السنة الواحدة."},
    {"id":469,"q":"حسب المادة (66)، إجازة الحج مدتها:","op":["أ. أربعة عشر يوماً","ب. واحد وعشرون يوماً","ج. ثلاثين يوماً","د. سبعة أيام"],"a":"أ. أربعة عشر يوماً","e":"المادة (66): لكل عامل الحق في إجازة مدفوعة الأجر لمدة لا تقل عن أربعة عشر يوماً لأداء فريضة الحج."},
    {"id":470,"q":"حسب المادة (67)، إجازة تربية الطفل مدتها:","op":["أ. سنة واحدة","ب. ستة أشهر","ج. شهرين","د. ثلاثة أشهر"],"a":"أ. سنة واحدة","e":"المادة (67): للمرأة العاملة الحق في الحصول على إجازة بدون أجر لمدة سنة واحدة لتربية طفلها."},
    {"id":471,"q":"حسب المادة (68)، إجازة مرافقة الزوج مدتها:","op":["أ. سنتان","ب. سنة","ج. ستة أشهر","د. ثلاثة أشهر"],"a":"أ. سنتان","e":"المادة (68): لكل من الزوجين العاملين الحق في الحصول على إجازة بدون أجر لمدة لا تزيد على سنتين لمرافقة زوجه."},
    {"id":472,"q":"حسب المادة (70)، إجازة الأمومة مدتها:","op":["أ. عشرة أسابيع","ب. ثمانية أسابيع","ج. ستة أسابيع","د. اثنا عشر أسبوعاً"],"a":"أ. عشرة أسابيع","e":"المادة (70): للمرأة العاملة الحق في إجازة أمومة بأجر كامل لمدة عشرة أسابيع."},
    {"id":473,"q":"حسب المادة (71)، إجازة الوضع قبل الولادة لا تزيد على:","op":["أ. أربعة أسابيع","ب. ستة أسابيع","ج. أسبوعين","د. شهرين"],"a":"أ. أربعة أسابيع","e":"المادة (71): يجوز للعاملة الحصول على إجازة وضع قبل الولادة بشرط ألا تزيد على أربعة أسابيع."},
    {"id":474,"q":"حسب المادة (72)، فترة الراحة للرضاعة لا تزيد على:","op":["أ. ساعة واحدة في اليوم","ب. ساعتين في اليوم","ج. نصف ساعة في اليوم","د. ثلاث ساعات في اليوم"],"a":"أ. ساعة واحدة في اليوم","e":"المادة (72): لا تقل في مجموعها عن ساعة واحدة في اليوم."},
    {"id":475,"q":"حسب المادة (73)، سن العمل القانوني هو:","op":["أ. ستة عشر سنة","ب. خمسة عشر سنة","ج. ثمانية عشر سنة","د. أربعة عشر سنة"],"a":"أ. ستة عشر سنة","e":"المادة (73): يجب ألا يقل سن الحدث عن ست عشرة سنة ميلادية."},
    {"id":476,"q":"حسب المادة (74)، الأعمال الخطرة يحددها:","op":["أ. وزير العمل","ب. النقابة","ج. المحكمة","د. مجلس الوزراء"],"a":"أ. وزير العمل","e":"المادة (74): يجوز للوزير تحديد الأعمال الخطرة أو الضارة بالصحة التي يحظر تشغيل الأحداث فيها."},
    {"id":477,"q":"حسب المادة (75)، ساعات عمل الأحداث لا تزيد عن:","op":["أ. ست ساعات","ب. ثماني ساعات","ج. أربع ساعات","د. سبع ساعات"],"a":"أ. ست ساعات","e":"المادة (75): لا يجوز تشغيل الحدث أكثر من ست ساعات يومياً."},
    {"id":478,"q":"حسب المادة (79)، المرأة الحامل لا يجوز تشغيلها في الأعمال:","op":["أ. الخطرة","ب. الإدارية","ج. المكتبية","د. التجارية"],"a":"أ. الخطرة","e":"المادة (79): يحظر تشغيل المرأة الحامل في الأعمال الضارة بالصحة أو الأعمال الشاقة."},
    {"id":479,"q":"حسب المادة (80)، يجب توفير وسائل الوقاية من:","op":["أ. الحريق والانفجار","ب. الأمطار","ج. الرياح","د. الرطوبة"],"a":"أ. الحريق والانفجار","e":"المادة (80): على صاحب العمل اتخاذ الاحتياطات اللازمة لحماية المؤسسة والعاملين فيها من أخطار الحريق والانفجارات."},
    {"id":480,"q":"حسب المادة (81)، يحظر إدخال المخدرات في:","op":["أ. مكان العمل","ب. المنزل","ج. السيارة","د. مكان الإقامة"],"a":"أ. مكان العمل","e":"المادة (81): لا يجوز للعامل أو العامل أن يدخل أو يستعمل في مكان العمل أي نوع من المواد المخدرة."},
    {"id":481,"q":"حسب المادة (83)، الفحوصات الطبية يجب أن تتم:","op":["أ. بشكل دوري","ب. مرة واحدة","ج. سنوياً","د. كل خمس سنوات"],"a":"أ. بشكل دوري","e":"المادة (83): على صاحب العمل أن يخضع العامل للفحوصات الطبية قبل التحاقه بالعمل وبشكل دوري."},
    {"id":482,"q":"حسب المادة (84)، عقوبة مخالفة الصحة والسلامة هي:","op":["أ. غرامة 100-500 دينار","ب. غرامة 500-1000 دينار","ج. الحبس","د. إغلاق المؤسسة"],"a":"أ. غرامة 100-500 دينار","e":"المادة (84): تحكم المحكمة على المخالف بغرامة لا تقل عن مائة دينار ولا تزيد على خمسمائة دينار."},
    {"id":483,"q":"حسب المادة (85)، الوحدات الطبية تنشأ في:","op":["أ. المنشآت التي يوجد بها 10 عمال فأكثر","ب. المنشآت التي يوجد بها 20 عاملاً","ج. المنشآت التي يوجد بها 5 عمال","د. جميع المنشآت"],"a":"أ. المنشآت التي يوجد بها 10 عمال فأكثر","e":"المادة (85): على صاحب العمل الذي يستخدم عشرة عمال فأكثر أن ينشئ وحدة طبية."},
    {"id":484,"q":"حسب المادة (87)، نفقات نقل وإسعاف المصاب:","op":["أ. يتحملها صاحب العمل","ب. يتحملها العامل","ج. تتحملها الدولة","د. تتحملها النقابة"],"a":"أ. يتحملها صاحب العمل","e":"المادة (87): ويتحمل صاحب العمل نفقات نقل المصاب إلى المستشفى أو المركز الطبي لمعالجته."},
    {"id":485,"q":"حسب المادة (88)، صاحب العمل مسؤول عن:","op":["أ. التعويض عن الأمراض المهنية","ب. نقل العامل","ج. تأهيل العامل","د. علاج العامل"],"a":"أ. التعويض عن الأمراض المهنية","e":"المادة (88): يكون صاحب العمل مسؤولاً عن دفع التعويض المنصوص عليه في هذا القانون للعامل الذي يصاب بمرض من الأمراض المهنية."},
    {"id":486,"q":"حسب المادة (90)، التعويض عن العجز الدائم الكلي:","op":["أ. 75% من الأجر لمدة سنتين","ب. 100% من الأجر","ج. 50% من الأجر","د. 25% من الأجر"],"a":"أ. 75% من الأجر لمدة سنتين","e":"المادة (90): إذا نشأ عن إصابة العمل عجز دائم كلي فيستحق العامل تعويضاً يعادل 75% من أجره عن مدة سنتين."},
    {"id":487,"q":"حسب المادة (92)، طلب التعويض يقدم خلال:","op":["أ. مدة محددة","ب. أي وقت","ج. سنة","د. شهرين"],"a":"أ. مدة محددة","e":"المادة (92): يتم تقدير التعويض الواجب دفعه بمقتضى هذا القانون بناء على طلب صاحب العمل أو العامل أو المستحقين عنه."},
    {"id":488,"q":"حسب المادة (94)، سقوط الحق في التعويض إذا كانت الإصابة:","op":["أ. ناتجة عن خطأ جسيم","ب. ناتجة عن حادث عادي","ج. ناتجة عن مرض وراثي","د. ناتجة عن إهمال صاحب العمل"],"a":"أ. ناتجة عن خطأ جسيم","e":"المادة (94): إذا نشأت الإصابة عن فعل متعمد أو عن خطأ أو إهمال جسيمين من المصاب."},
    {"id":489,"q":"حسب المادة (95)، الحد الأدنى للتعويض:","op":["أ. 1000 دينار","ب. 500 دينار","ج. 2000 دينار","د. 2500 دينار"],"a":"أ. 1000 دينار","e":"المادة (95): لا يجوز في أي حالة من الحالات رهن التعويض الواجب دفعه بمقتضى أحكام هذا القانون أو الحجز عليه إلا لدين النفقة وفقاً لأحكام القانون."},
